import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Chip,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { buildApiUrl } from '../../config/apiConfig';
import {
  DEFAULT_PARTNER_API_ENDPOINTS,
  DEFAULT_PARTNER_API_SCOPES,
  DEFAULT_PARTNER_AUTH,
  PARTNER_API_ENDPOINT_DETAILS,
  PARTNER_PORTAL_ENDPOINTS,
} from '../../constants/partnerApiDocumentation';
import { PARTNER_SUPPORT_EMAIL } from '../../constants/partnerProgram';

interface IntegrationCatalog {
  version: string;
  authentication: {
    type: string;
    headerOptions: string[];
    keyPrefix: string;
    note: string;
  };
  scopes: { id: string; description: string }[];
  endpoints: { method: string; path: string; access: string; scopes?: string[] }[];
  supportEmail: string;
}

const PartnerApiDocumentationContent: React.FC = () => {
  const [catalog, setCatalog] = useState<IntegrationCatalog | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch(buildApiUrl('/v1/public/integration-catalog'))
      .then(async (res) => {
        const body = await res.json();
        if (!res.ok || !body.success) {
          throw new Error(body.message || 'Failed to load integration catalog');
        }
        setCatalog(body.data);
      })
      .catch((err: Error) => setError(err.message));
  }, []);

  const supportEmail = catalog?.supportEmail || PARTNER_SUPPORT_EMAIL;
  // Origin only — paths below already include `/api/...` (avoid `/api//api/` doubling).
  const apiBase = buildApiUrl('/')
    .replace(/\/+$/, '')
    .replace(/\/api$/i, '');
  const authHeaders = catalog?.authentication.headerOptions || DEFAULT_PARTNER_AUTH.headerOptions;
  const keyPrefix = catalog?.authentication.keyPrefix || DEFAULT_PARTNER_AUTH.keyPrefix;
  const scopes = catalog?.scopes || DEFAULT_PARTNER_API_SCOPES;
  const endpoints = catalog?.endpoints || DEFAULT_PARTNER_API_ENDPOINTS;

  return (
    <Stack spacing={3}>
      {error && (
        <Alert severity="warning">
          Live catalog unavailable ({error}). Reference documentation below is still valid; retry after the API
          is reachable.
        </Alert>
      )}

      <Paper variant="outlined" sx={{ p: { xs: 2, md: 2.5 } }}>
        <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
          Authentication
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Send your partner API key using either header format. Keys use the <code>{keyPrefix}</code> prefix and
          are issued when you register as a partner or when an administrator provisions your application.
        </Typography>
        <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
          {authHeaders.map((header) => (
            <Chip key={header} label={header} size="small" variant="outlined" />
          ))}
        </Stack>
        <Typography variant="body2" color="text.secondary">
          Invalid or revoked keys return HTTP 401. Partner portal dashboards use JWT from{' '}
          <code>POST /api/auth/login</code> with your partner account credentials.
        </Typography>
      </Paper>

      <Paper variant="outlined" sx={{ p: { xs: 2, md: 2.5 } }}>
        <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
          Scopes
        </Typography>
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Scope</TableCell>
                <TableCell>Capability</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {scopes.map((scope) => (
                <TableRow key={scope.id}>
                  <TableCell>
                    <code>{scope.id}</code>
                  </TableCell>
                  <TableCell>{scope.description}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      <Paper variant="outlined" sx={{ p: { xs: 2, md: 2.5 } }}>
        <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
          Public &amp; partner REST endpoints
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          Base URL: <code>{apiBase}/api</code>
          {catalog ? ` · Catalog version ${catalog.version}` : ''}
        </Typography>
        <TableContainer sx={{ overflowX: 'auto' }}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Method</TableCell>
                <TableCell>Path</TableCell>
                <TableCell>Access</TableCell>
                <TableCell>Scopes</TableCell>
                <TableCell>Details</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {endpoints.map((endpoint) => {
                const detailKey = `${endpoint.method} ${endpoint.path}`;
                const detail = PARTNER_API_ENDPOINT_DETAILS[detailKey];
                return (
                  <TableRow key={detailKey}>
                    <TableCell>{endpoint.method}</TableCell>
                    <TableCell>
                      <code>{endpoint.path}</code>
                    </TableCell>
                    <TableCell>{endpoint.access}</TableCell>
                    <TableCell>{endpoint.scopes?.length ? endpoint.scopes.join(', ') : '—'}</TableCell>
                    <TableCell>
                      <Typography variant="body2">{detail?.description || '—'}</Typography>
                      {detail?.queryParams && (
                        <Typography variant="caption" color="text.secondary" display="block">
                          Query: {detail.queryParams}
                        </Typography>
                      )}
                      {detail?.responseNotes && (
                        <Typography variant="caption" color="text.secondary" display="block">
                          {detail.responseNotes}
                        </Typography>
                      )}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      <Paper variant="outlined" sx={{ p: { xs: 2, md: 2.5 } }}>
        <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
          Partner portal account API
        </Typography>
        <Typography variant="body2" color="text.secondary" paragraph>
          After registering as a partner, sign in at <code>/login</code> to access usage dashboards at{' '}
          <code>/partner/dashboard</code>. These endpoints require a partner JWT.
        </Typography>
        <TableContainer sx={{ overflowX: 'auto' }}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Method</TableCell>
                <TableCell>Path</TableCell>
                <TableCell>Access</TableCell>
                <TableCell>Description</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {PARTNER_PORTAL_ENDPOINTS.map((endpoint) => (
                <TableRow key={`${endpoint.method}-${endpoint.path}`}>
                  <TableCell>{endpoint.method}</TableCell>
                  <TableCell>
                    <code>{endpoint.path}</code>
                  </TableCell>
                  <TableCell>{endpoint.access}</TableCell>
                  <TableCell>{endpoint.description}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      <Paper variant="outlined" sx={{ p: { xs: 2, md: 2.5 } }}>
        <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
          Example request
        </Typography>
        <Box
          component="pre"
          sx={{
            p: 2,
            bgcolor: 'action.hover',
            borderRadius: 1,
            overflow: 'auto',
            fontSize: '0.85rem',
            m: 0,
          }}
        >
          {`curl -s -H "X-API-Key: $PARTNER_API_KEY" \\
  "${apiBase}/api/v1/partners/msmes?limit=5"`}
        </Box>
        <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
          Partner responses exclude passwords, full transaction line items, and document binaries. Rotate keys
          through your administrator when staff change roles. OpenAPI spec:{' '}
          <code>{apiBase}/api/v1/public/openapi.json</code>. Sustainow Hub is first-party and uses{' '}
          <code>/api/v1/internal</code> with a platform key, not these partner keys. Optional client{' '}
          <code>@sustainow/carbon-intelligence-sdk</code>. For technical support, email{' '}
          <a href={`mailto:${supportEmail}`}>{supportEmail}</a>.
        </Typography>
      </Paper>
    </Stack>
  );
};

export default PartnerApiDocumentationContent;
